// Global search over the build-time index (public/search-index.json).
//
// The index is generated by scripts/build-search-index.mjs from the committed
// cards / echoes / quiz data. Nothing is fetched at page load: the overlay
// calls SearchService.loadIndex() the first time it opens, and the same
// promise/index serves every later query for the rest of the session.
//
// Search is pure once the index is in memory: tokens are lowercased and
// diacritic-folded, every token must match the name or an alias (AND), and
// primary-name hits outrank alias hits. Results are grouped Cards / Echoes /
// Questions in that order and capped per group so the overlay stays compact.
/** Same-origin location Vite copies from public/ into dist/. */
export const SEARCH_INDEX_URL = '/search-index.json';

/** Structure version understood by this client. */
export const SEARCH_INDEX_SCHEMA_VERSION = 1;

/** Maximum results returned per group (the overlay renders all groups). */
export const RESULT_LIMIT = 6;

/** Group order and user-facing headings: Cards / Echoes / Questions. */
export const SEARCH_GROUPS = Object.freeze([
  { type: 'card', label: 'Cards' },
  { type: 'echo', label: 'Echoes' },
  { type: 'question', label: 'Questions' },
]);

// Edge punctuation (quotes, commas, CJK punctuation) never belongs to a
// search token: "Glacius," and "赫敏、" behave like their clean forms.
const EDGE_PUNCTUATION = /^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu;

// Word-boundary hits only apply to Latin/digit tokens; CJK has no spaces, so
// every substring hit there is meaningful.
const LATIN_TOKEN = /^[a-z0-9]+$/;

/**
 * Fold text for matching: compatibility-normalize, drop combining accents and
 * apostrophes, lowercase, collapse whitespace. "Luna’s" -> "lunas".
 */
export function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['’]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Split a raw query into distinct search tokens. Whitespace separates tokens;
 * edge punctuation is stripped and empty tokens are discarded.
 */
export function tokenizeQuery(query) {
  const normalized = normalizeText(query);
  if (!normalized) return [];
  const tokens = normalized
    .split(' ')
    .map((token) => token.replace(EDGE_PUNCTUATION, ''))
    .filter(Boolean);
  return [...new Set(tokens)];
}

/**
 * Score one token against one text field. Zero means "no match".
 *
 * Primary-name hits (120/70/40) beat alias hits (55/30/18) so an exact card
 * name always lands above a card whose description-ish alias merely mentions
 * it. Latin substring hits must start at a word boundary — "ron" must not
 * match "Hermione" through the middle of the word; CJK substring hits always
 * count because Chinese has no word separators.
 */
function fieldScore(text, token, isPrimaryName) {
  if (!text) return 0;
  if (text === token) return isPrimaryName ? 120 : 55;

  const index = text.indexOf(token);
  if (index === -1) return 0;

  const isLatinToken = LATIN_TOKEN.test(token);
  if (isLatinToken && index > 0) {
    const before = text[index - 1];
    const atWordBoundary = !/[a-z0-9]/.test(before);
    if (!atWordBoundary) return 0;
  }

  if (index === 0) return isPrimaryName ? 70 : 30;
  return isPrimaryName ? 40 : 18;
}

function prepareEntry(entry) {
  const aliases = Array.isArray(entry?.aliases)
    ? entry.aliases.map(normalizeText).filter(Boolean)
    : [];
  return {
    entry,
    name: normalizeText(entry?.name),
    aliases,
  };
}

function scoreEntry(prepared, tokens) {
  let total = 0;
  for (const token of tokens) {
    let best = fieldScore(prepared.name, token, true);
    if (best < 120) {
      for (const alias of prepared.aliases) {
        best = Math.max(best, fieldScore(alias, token, false));
      }
    }
    if (best === 0) return 0; // every token must match (AND)
    total += best;
  }
  return total;
}

function compareScored(a, b) {
  if (b.score !== a.score) return b.score - a.score;
  // Shorter names win ties: "Glacius" before "Glacius Maxima" when both are
  // prefixes, and the compact label is usually the entity itself.
  if (a.name.length !== b.name.length) return a.name.length - b.name.length;
  return a.name.localeCompare(b.name);
}

/**
 * Search one in-memory index document.
 *
 * @param {{ entries?: Array }} index as written by build-search-index.mjs.
 * @param {string} query raw user input.
 * @param {{ limit?: number }} [options] per-group result cap (default 6).
 * @returns {{
 *   query: string,
 *   tokens: string[],
 *   total: number,
 *   groups: Array<{
 *     type: string, label: string, total: number, results: Array<object>,
 *   }>,
 * }}
 *   `total` counts every match before the cap; each group's `total` does the
 *   same for its own type. Groups with no hits are omitted.
 */
export function searchIndex(index, query, { limit = RESULT_LIMIT } = {}) {
  const trimmed = String(query ?? '').trim();
  const tokens = tokenizeQuery(trimmed);
  const entries = Array.isArray(index?.entries) ? index.entries : [];
  if (tokens.length === 0 || entries.length === 0) {
    return { query: trimmed, tokens, total: 0, groups: [] };
  }

  const cap = Math.max(1, Math.floor(Number(limit) || RESULT_LIMIT));
  const byType = new Map(SEARCH_GROUPS.map((group) => [group.type, []]));

  for (const entry of entries) {
    const bucket = byType.get(entry?.type);
    if (!bucket) continue; // unknown types are ignored, not rendered
    const score = scoreEntry(prepareEntry(entry), tokens);
    if (score === 0) continue;
    bucket.push({ ...entry, score });
  }

  const groups = [];
  let total = 0;
  for (const { type, label } of SEARCH_GROUPS) {
    const matches = byType.get(type);
    if (!matches.length) continue;
    total += matches.length;
    matches.sort(compareScored);
    groups.push({
      type,
      label,
      total: matches.length,
      results: matches.slice(0, cap),
    });
  }

  return { query: trimmed, tokens, total, groups };
}

export class SearchService {
  /** Parsed index document, or null until loadIndex() succeeds. */
  static index = null;

  /** Shared in-flight request; prevents duplicate fetches while opening. */
  static inFlight = null;

  /** Whether the index is already in memory. */
  static get loaded() {
    return SearchService.index !== null;
  }

  /**
   * Fetch and cache the index. Safe to call repeatedly and concurrently; the
   * successful document is reused for the rest of the session. A failed load
   * clears the in-flight promise so the next overlay open retries.
   *
   * @param {{ fetchImpl?: Function, url?: string }} [options] injection point
   *   for unit tests (defaults to the global fetch and the site URL).
   * @returns {Promise<object>} the parsed index.
   */
  static async loadIndex({
    fetchImpl = globalThis.fetch,
    url = SEARCH_INDEX_URL,
  } = {}) {
    if (SearchService.index) return SearchService.index;
    if (!SearchService.inFlight) {
      SearchService.inFlight = Promise.resolve()
        .then(() => {
          if (typeof fetchImpl !== 'function') {
            throw new Error('No fetch implementation is available.');
          }
          return fetchImpl(url);
        })
        .then((response) => {
          if (!response?.ok) {
            throw new Error(
              `Failed to fetch ${url}: HTTP ${response?.status ?? 'unknown'}`,
            );
          }
          return response.json();
        })
        .then((data) => {
          if (
            !data ||
            typeof data !== 'object' ||
            !Array.isArray(data.entries)
          ) {
            throw new Error(
              `${url} is malformed: expected an object with an "entries" array.`,
            );
          }
          if (
            data.version !== undefined &&
            data.version !== SEARCH_INDEX_SCHEMA_VERSION
          ) {
            throw new Error(
              `${url} has schema version ${JSON.stringify(data.version)}; ` +
                `this client understands ${SEARCH_INDEX_SCHEMA_VERSION}.`,
            );
          }
          SearchService.index = data;
          return data;
        })
        .finally(() => {
          SearchService.inFlight = null;
        });
    }
    return SearchService.inFlight;
  }

  /** Pure search over the loaded index (empty result before load). */
  static search(query, options) {
    return searchIndex(SearchService.index, query, options);
  }

  /** Test hook: forget the cached index and any in-flight request. */
  static reset() {
    SearchService.index = null;
    SearchService.inFlight = null;
  }
}
